-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist ein Virenschutz in TDD-Projekten notwendig, um die Sicherheit des Quellcodes zu gewährleisten?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt vor Malware während Entwicklung"}, {"text": "Nein", "correct": false, "because": "Sicherheit essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Virenschutz in TDD die Integrität von Testdaten beeinträchtigen?', 2, '[{"text": "Nein", "correct": true, "because": "Virenschutz schützt, ohne Tests zu stören"}, {"text": "Ja", "correct": false, "because": "Keine direkte Beeinflussung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Virenschutzmaßnahmen in der TDD-Dokumentation explizit erwähnt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Tests, nicht Sicherheit"}, {"text": "Ja", "correct": false, "because": "Optional, nicht Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Virenschutzlösungen in TDD die Ausführungsgeschwindigkeit von Tests verlangsamen?', 2, '[{"text": "Ja", "correct": true, "because": "Scans können Ressourcen beanspruchen"}, {"text": "Nein", "correct": false, "because": "Mögliche Verlangsamung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Virenschutz in TDD nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Schutz immer wichtig"}, {"text": "Ja", "correct": false, "because": "Größe unabhängig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein Virenschutz in TDD?', 2, '[{"text": "Schutz vor externen Bedrohungen", "correct": true, "because": "Sichert Entwicklungsprozess"}, {"text": "Optimierung von Tests", "correct": false, "because": "Nicht primär"}, {"text": "Ersetzung von Tests", "correct": false, "because": "Unterschiedliche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt des Virenschutzes ist in TDD besonders wichtig?', 3, '[{"text": "Echtzeitschutz", "correct": true, "because": "Schützt während Entwicklung"}, {"text": "Manuelle Scans", "correct": false, "because": "Weniger effizient"}, {"text": "Dokumentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung kann ein Virenschutz in TDD mit sich bringen?', 2, '[{"text": "Performance-Einbußen", "correct": true, "because": "Ressourcenverbrauch möglich"}, {"text": "Testfehler", "correct": false, "because": "Unwahrscheinlich"}, {"text": "Komplexere Tests", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie sollte ein Virenschutz in TDD-Dokumentationen erwähnt werden?', 2, '[{"text": "Als Sicherheitsmaßnahme", "correct": true, "because": "Kontextrelevant"}, {"text": "Als Testanforderung", "correct": false, "because": "Nicht primär"}, {"text": "Als Optimierungstool", "correct": false, "because": "Falsche Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich durch Virenschutz in TDD?', 2, '[{"text": "Sicherer Entwicklungsprozess", "correct": true, "because": "Schutz vor Malware"}, {"text": "Weniger Tests nötig", "correct": false, "because": "Tests bleiben"}, {"text": "Schnellere Iterationen", "correct": false, "because": "Nicht primär"}]'),

