('00000000-0000-0000-0000-000000000000', 'Welche Funktionen sollte ein Virensch EXISTenz in TDD erfüllen?', 4, '[{"text": "Echtzeitschutz", "correct": true, "because": "Schützt während Arbeit"}, {"text": "Malware-Erkennung", "correct": true, "because": "Sichert Code"}, {"text": "Testgenerierung", "correct": false, "because": "Nicht Aufgabe"}, {"text": "Datenintegrität", "correct": true, "because": "Verhindert Manipulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Virenschutz in TDD?', 3, '[{"text": "Schutz vor Malware", "correct": true, "because": "Sichert Entwicklung"}, {"text": "Verbesserte Testqualität", "correct": false, "because": "Nicht primär"}, {"text": "Sicherung von Testdaten", "correct": true, "because": "Integrität gewährleistet"}, {"text": "Reduzierte Bedrohungen", "correct": true, "because": "Risiken minimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen kann ein Virenschutz in TDD mit sich bringen?', 3, '[{"text": "Performance-Verlangsamung", "correct": true, "because": "Ressourcenverbrauch"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Mögliche Konflikte"}, {"text": "Schnellere Tests", "correct": false, "because": "Eher Verlangsamung"}, {"text": "Erhöhter Wartungsaufwand", "correct": true, "because": "Updates nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten in der Dokumentation zu Virenschutz in TDD erwähnt werden?', 4, '[{"text": "Eingesetzte Software", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Sicherheitsrichtlinien", "correct": true, "because": "Schutzvorgaben"}, {"text": "Testdetails", "correct": false, "because": "Nicht primär"}, {"text": "Update-Häufigkeit", "correct": true, "because": "Aktualität wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Best Practices gelten für den Virenschutz in TDD?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schutz aktuell halten"}, {"text": "Minimale Systembelastung", "correct": true, "because": "Effizienz wichtig"}, {"text": "Manuelle Scans", "correct": false, "because": "Automatisierung bevorzugt"}, {"text": "Integration in CI", "correct": true, "because": "Automatisierung unterstützt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Virenschutz in TDD schützt vor externen Bedrohungen. b) Virenschutz ersetzt Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, Tests bleiben"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Virenschutz kann die Testausführung verlangsamen. b) Virenschutz ist in TDD optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verlangsamung möglich, Schutz empfohlen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Virenschutz sollte in TDD dokumentiert werden. b) Virenschutz ist nur für große Projekte nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation hilfreich, Größe egal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Virenschutz sichert Testdaten in TDD. b) Virenschutz beeinträchtigt Testqualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daten geschützt, Qualität unbeeinflusst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Virenschutz in TDD unterstützt CI-Systeme. b) Virenschutz ist in TDD unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CI profitiert, Schutz relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

